<?php
declare(strict_types=1);
namespace App\Services; use App\Core\Database;
final class DashboardService { public function stats(int $userId):array{$pdo=Database::connection();$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted"');$s->execute([$userId]);$total=(float)$s->fetchColumn();$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted" AND DATE_FORMAT(expense_date,"%Y-%m")=DATE_FORMAT(CURDATE(),"%Y-%m")');$s->execute([$userId]);$month=(float)$s->fetchColumn();$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted" AND expense_date=CURDATE()');$s->execute([$userId]);$today=(float)$s->fetchColumn();$budget=(float)$pdo->query('SELECT COALESCE(SUM(budget_amount),0) FROM budgets WHERE status="active" AND start_date<=CURDATE() AND end_date>=CURDATE()')->fetchColumn();$balance=(float)$pdo->query('SELECT COALESCE(SUM(current_balance),0) FROM accounts WHERE status="active"')->fetchColumn();$byCat=$pdo->prepare('SELECT c.name label,COALESCE(SUM(e.amount),0) value FROM expenses e JOIN categories c ON c.id=e.category_id WHERE e.user_id=? AND e.status="posted" GROUP BY c.id ORDER BY value DESC LIMIT 8');$byCat->execute([$userId]);$monthly=$pdo->prepare('SELECT DATE_FORMAT(expense_date,"%b") label,ROUND(SUM(amount),2) value FROM expenses WHERE user_id=? AND status="posted" AND expense_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY YEAR(expense_date),MONTH(expense_date) ORDER BY YEAR(expense_date),MONTH(expense_date)');$monthly->execute([$userId]);return compact('total','month','today','budget','balance')+['remaining'=>$budget-$month,'byCategory'=>$byCat->fetchAll(),'monthly'=>$monthly->fetchAll()];}}
